/**
 * The built-in bots' library: every module a plane bot runs (its import graph from bots/policy.ts and the plane bot
 * classes, rules leaves, geometry, nav), as the JavaScript Node itself runs (`stripTypeScriptTypes`), served in the
 * strategy skill under BOT_LIBRARY_DIR. Bot packages and starter forks import it from there, so the code a bot seat
 * runs is the code an agent reads in `game_skill` and forks. Generated by `pnpm bots:build` (bots/build.ts).
 */
import { readFileSync } from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';

/**
 * Skill directory of the library: `src/<path>.ts` is served as `<BOT_LIBRARY_DIR>/<path>.js`, and a plain JavaScript
 * module `src/<path>.js` (util/fdlibm.js, vendored verbatim) as itself.
 */
export const BOT_LIBRARY_DIR = 'policies/game';
/** The modules a bot package or starter imports (bots/starter.ts: the starters' knobs and tiers); the library is their import graph. */
export const BOT_LIBRARY_ROOTS = ['bots/policy.ts', 'bots/starter.ts', 'bots/depths.ts', 'bots/surface.ts', 'bots/sky.ts', 'bots/orbit.ts'] as const;

const SRC = new URL('../', import.meta.url);
/** A static import or re-export specifier (after stripping, every one left is a runtime import). */
const SPECIFIER = /(\bfrom\s*|\bimport\s*)(['"])([^'"]+)\2/g;
const RELATIVE_MODULE = /^\.{1,2}\/.+\.[jt]s$/;

const header = (path: string): string =>
  `// Agent Command's built-in bot library: packages/game/src/${path}${path.endsWith('.ts') ? ', types stripped' : ''} (pnpm bots:build). Read it, import it,\n` +
  `// or fork a module by copying it into your own policy modules (skill policies.md, "The built-in bots' source").\n`;

/**
 * `source` with its TypeScript erased for reading: every run of spaces that type erasure left (a run holding a
 * character that was type syntax) becomes one space when the original had one at its end (`x: T = 1` → `x = 1`), else
 * nothing (`f(a: T, b)` → `f(a, b)`); a line that held only types is dropped, with the doc comment right above it.
 * Whitespace and comments only: `bots:build` checks that this text bundles to exactly the script of Node's plain
 * stripped text.
 */
function readable(source: string, stripped: string): string {
  const from = source.split('\n');
  const to = stripped.split('\n');
  if (from.length !== to.length) throw new Error('type stripping changed the line count');
  const out: string[] = [];
  for (let i = 0; i < to.length; i++) {
    const a = from[i]!, b = to[i]!;
    if (a === b) { out.push(b); continue; }
    if (b.trim() === '') {
      // The first line of an erased declaration: the doc comment just above it goes with it.
      if (out.at(-1)?.trimEnd().endsWith('*/') && to[i - 1] === from[i - 1]) {
        let start = out.length - 1;
        while (start > 0 && !out[start]!.trimStart().startsWith('/**') && out[start - 1]!.trimStart().startsWith('*')) start--;
        if (out[start]!.trimStart().startsWith('/**')) out.length = start;
      }
      continue;
    }
    if (a.length !== b.length) { out.push(b.trimEnd()); continue; }
    let line = '';
    for (let j = 0; j < b.length;) {
      if (b[j] !== ' ') { line += b[j++]; continue; }
      let end = j, erased = false;
      for (; end < b.length && b[end] === ' '; end++) if (a[end] !== ' ') erased = true;
      line += !erased ? b.slice(j, end) : a[end - 1] === ' ' && end < b.length ? ' ' : '';
      j = end;
    }
    out.push(line.trimEnd());
  }
  return out.join('\n');
}

export interface BotLibrary {
  /** Skill-relative path (`policies/game/<path>.js`) → served module text. */
  readonly files: ReadonlyMap<string, string>;
  /** The same modules as Node's plain stripped text (checkLibrary). */
  readonly plain: ReadonlyMap<string, string>;
}

/** The library from the current `src/` (synchronous: reads and strips its import graph). */
export function botLibrary(): BotLibrary {
  const files = new Map<string, string>();
  const plain = new Map<string, string>();
  const pending: string[] = [...BOT_LIBRARY_ROOTS];
  const seen = new Set<string>(pending);
  while (pending.length > 0) {
    const path = pending.pop()!;
    const source = readFileSync(new URL(path, SRC), 'utf8');
    const stripped = path.endsWith('.ts') ? stripTypeScriptTypes(source) : source;
    const toJs = (text: string): string => text.replace(SPECIFIER, (all, kw: string, q: string, spec: string) => {
      if (!RELATIVE_MODULE.test(spec)) throw new Error(`${path}: the bot library imports ${spec}; bots import only relative game modules`);
      const target = new URL(spec, new URL(path, SRC)).pathname.slice(SRC.pathname.length);
      if (!seen.has(target)) { seen.add(target); pending.push(target); }
      return `${kw}${q}${spec.slice(0, -3)}.js${q}`;
    });
    const served = `${BOT_LIBRARY_DIR}/${path.slice(0, -3)}.js`;
    files.set(served, header(path) + toJs(readable(source, stripped)));
    plain.set(served, header(path) + toJs(stripped));
  }
  const sorted = (m: Map<string, string>) => new Map([...m].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
  return { files: sorted(files), plain: sorted(plain) };
}
